@page "/submit"
@rendermode InteractiveServer

@using RecipeHub.Models
@using RecipeHub.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe - RecipeHub</PageTitle>

<div class="container">
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/">Home</a></li>
            <li class="breadcrumb-item active">Submit Recipe</li>
        </ol>
    </nav>

    <h1 class="mb-4">📝 Submit Your Recipe</h1>

    @if (SubmitSuccess)
    {
        <div class="alert alert-success">
            <strong>Recipe submitted!</strong> Your recipe has been added to the community.
            <a href="/">Back to Home</a>
        </div>
    }
    else
    {
        <EditForm Model="Submission" OnValidSubmit="HandleSubmit" FormName="recipeForm">
            <DataAnnotationsValidator />

            <div class="mb-3">
                <label for="title" class="form-label">Recipe Title</label>
                <InputText id="title" class="form-control" @bind-Value="Submission.Title" placeholder="e.g. Grandma's Apple Pie" />
            </div>

            <div class="mb-3">
                <label for="category" class="form-label">Category</label>
                <InputSelect id="category" class="form-select" @bind-Value="Submission.Category">
                    <option value="">-- Select a category --</option>
                    <option value="Italian">Italian</option>
                    <option value="Indian">Indian</option>
                    <option value="Asian">Asian</option>
                    <option value="Mexican">Mexican</option>
                    <option value="Desserts">Desserts</option>
                    <option value="Other">Other</option>
                </InputSelect>
            </div>

            <div class="mb-3">
                <label for="ingredients" class="form-label">Ingredients (one per line)</label>
                <InputTextArea id="ingredients" class="form-control" rows="6" @bind-Value="Submission.Ingredients" placeholder="Flour&#10;Sugar&#10;Butter&#10;..." />
            </div>

            <div class="mb-3">
                <label for="steps" class="form-label">Steps (one per line)</label>
                <InputTextArea id="steps" class="form-control" rows="8" @bind-Value="Submission.Steps" placeholder="1. Preheat oven to 350°F&#10;2. Mix dry ingredients&#10;..." />
            </div>

            <button type="submit" class="btn btn-success btn-lg"
                    disabled="@(!IsFormValid)">
                Submit Recipe
            </button>
        </EditForm>
    }
</div>

@code {
    private RecipeSubmission Submission { get; set; } = new();
    private bool SubmitSuccess { get; set; }

    private bool IsFormValid =>
        !string.IsNullOrWhiteSpace(Submission.Title) &&
        !string.IsNullOrWhiteSpace(Submission.Category) &&
        !string.IsNullOrWhiteSpace(Submission.Ingredients) &&
        !string.IsNullOrWhiteSpace(Submission.Steps);

    private void HandleSubmit()
    {
        if (!IsFormValid) return;
        RecipeService.SubmitRecipe(Submission);
        SubmitSuccess = true;
    }
}

